    static ServerMatch abilityGame(String id,EnergyType type){return GeneratedRuleBatch8Test.fixture(List.of(ability(id)),type,type,GeneratedRuleBatch8Test.trainer("swsh5_en_124"),GeneratedRuleBatch8Test.hit(40,false));}
    static void select(ServerMatch m,List<UUID> ids){var p=m.effectCardPrompt(A);m.submitEffectCards(A,p.resolutionId(),p.step(),ids);if(m.effectCardReveal()!=null)m.acknowledgeEffectReveal(B,m.effectCardReveal().id());}
    public static void main(String[] args){fly();survive();damageGates();benchCounters();doubleHeadsKo();typedSearch();tealDance();discardCost();stadiumPoison();basicAttachment();returnEnergy();topSupporter();hpBall();switchAbility();fullProtection();System.out.println("GeneratedRuleBatch20Test passed: single-coin Fly, lethal survival boundaries, damage gates, public/private choices, typed searches, attachment-before-draw, exact costs, HP filter and temporary protection");}
    static void fly(){var fly=attack("bw1_en_086",0);var hit=DamageTriggeredAbilityTest.attack(30,",\"conditions\":[{\"target\":\"DEFENDER\",\"condition\":\"POISONED\"}]");boolean heads=false,tails=false;
        for(int seed=0;seed<40&&!(heads&&tails);seed++){var m=SharedUsageLimitTest.attackFixture(seed,List.of(),List.of(fly,hit));var a=m.currentPlayer();var b=a.equals(SharedUsageLimitTest.A)?SharedUsageLimitTest.B:SharedUsageLimitTest.A;int rng=m.randomTranscript().size();m.attack(a,fly.id());check(m.randomTranscript().size()==rng+1,"Fly flipped more than once");boolean passed=m.lastAttack().finalDamage()==50;heads|=passed;tails|=!passed;check(m.lastAttack().finalDamage()==(passed?50:0),"Fly printed damage");m.attack(b,hit.id());check(m.activePokemonView(a).damage()==(passed?0:40)&&m.activePokemonView(a).conditions().contains(SpecialCondition.POISONED)!=passed,"Fly damage and protection did not share a coin");if(passed){m.endTurn(a);m.attack(b,hit.id());check(m.activePokemonView(a).damage()==40,"Fly protection survived expiry");}}
        check(heads&&tails,"Both Fly outcomes not covered");
    }
    static void survive(){var a=ability("me2-5_en_116");boolean heads=false,tails=false;for(int seed=0;seed<40&&!(heads&&tails);seed++){
        var hit=DamageTriggeredAbilityTest.attack(500,",\"ignoresActiveDefenderDamageEffects\":true");var m=SharedUsageLimitTest.attackFixture(seed,List.of(a),List.of(hit));var actor=m.currentPlayer();var victim=actor.equals(SharedUsageLimitTest.A)?SharedUsageLimitTest.B:SharedUsageLimitTest.A;UUID host=active(m,victim);int rng=m.randomTranscript().size();m.attack(actor,hit.id());DamageTriggeredAbilityTest.finishTriggers(m);boolean saved=m.phase()==MatchPhase.TURN;heads|=saved;tails|=!saved;check(m.randomTranscript().size()==rng+1,"Lethal survival must flip exactly once");if(saved)check(active(m,victim).equals(host)&&m.activePokemonView(victim).damage()==290,"Tenacious Body did not leave 10 HP after overkill");
        }check(heads&&tails,"Both survival outcomes not covered");
        for(boolean direct:List.of(false,true)){var m=DamageTriggeredAbilityTest.fixture(DamageTriggeredAbilityTest.attack(0,""),a);int rng=m.randomTranscript().size();if(direct)m.knockOutPokemonByEffect(DamageTriggeredAbilityTest.A,DamageTriggeredAbilityTest.B,active(m,DamageTriggeredAbilityTest.B));else m.placeDamageCountersByEffect(DamageTriggeredAbilityTest.A,DamageTriggeredAbilityTest.B,active(m,DamageTriggeredAbilityTest.B),30);check(m.phase()==MatchPhase.PRIZE_SELECTION&&m.randomTranscript().size()==rng,"Survival activated for counters or direct KO");}
    }
    static void damageGates(){var injured=attack("rsv10-5_en_024",1);for(boolean damaged:List.of(false,true)){var m=game(injured);if(damaged)m.placeDamageCountersByEffect(A,B,active(m,B),1);m.attack(A,injured.id());check(m.lastAttack().finalDamage()==(damaged?50:0),"Bared Fangs checked post-damage condition");}
        var v=attack("rsv10-5_en_172",0);for(int n:List.of(4,5)){var m=game(v);while(m.benchPokemonView(A).size()<n)m.playBasicPokemonToBench(A,hand(m,A,"basic").instanceId());m.attack(A,v.id());check(m.lastAttack().finalDamage()==(n==5?120:0),"V-Force Bench threshold");}
    }
    static void benchCounters(){var a=attack("swsh10_en_064",0);var m=game(a);m.attack(A,a.id());var p=m.effectPokemonPrompt(A);check(p.targets().size()==1&&p.targets().getFirst().pokemonId().equals(bench(m,B)),"Counter prompt not opponent Bench");reject(()->m.chooseEffectPokemon(A,p.resolutionId(),p.step(),active(m,B)));reject(()->m.chooseEffectPokemon(B,p.resolutionId(),p.step(),bench(m,B)));m.chooseEffectPokemon(A,p.resolutionId(),p.step(),bench(m,B));check(m.benchPokemonView(B).getFirst().damage()==20&&m.activePokemonView(B).damage()==50,"Bench counters confused with attack damage");}
    static void doubleHeadsKo(){var a=attack("sm9_en_009",1);boolean ko=false,miss=false;for(int seed=0;seed<60&&!(ko&&miss);seed++){var m=SharedUsageLimitTest.attackFixture(seed,List.of(),List.of(a));int rng=m.randomTranscript().size();m.attack(m.currentPlayer(),a.id());boolean success=m.phase()==MatchPhase.PRIZE_SELECTION;ko|=success;miss|=!success;check(m.randomTranscript().size()==rng+2,"Guillotine Hug coin count");}check(ko&&miss,"Both direct KO outcomes");}
    static void typedSearch(){var a=ability("sv2_en_061");var m=abilityGame("sv2_en_061",EnergyType.WATER);reject(()->m.useAbility(A,bench(m,A),a.id()));m.useAbility(A,active(m,A),a.id());var p=m.effectCardPrompt(A);check(p.maximum()==2&&p.minimum()==0&&p.candidates().stream().allMatch(c->c.definitionId().equals("energy")),"Shivery Chill omitted Basic/type filter");select(m,p.candidates().stream().limit(2).map(CardInstance::instanceId).toList());reject(()->m.useAbility(A,active(m,A),a.id()));
        var t=ability("sv1_en_081");var n=abilityGame("sv1_en_081",EnergyType.LIGHTNING);n.useAbility(A,bench(n,A),t.id());var q=n.effectCardPrompt(A);check(q.candidates().stream().allMatch(c->n.cardDefinition(c.definitionId()).basicPokemon()&&n.cardDefinition(c.definitionId()).pokemonTypes().contains(EnergyType.LIGHTNING)),"Tandem Unit filter");var chosen=q.candidates().stream().limit(2).map(CardInstance::instanceId).toList();int count=n.benchPokemonView(A).size();select(n,chosen);check(n.benchPokemonView(A).size()==count+chosen.size()&&n.effectCardReveal()==null,"Tandem Unit did not put selected cards onto Bench");
    }
    static void tealDance(){for(boolean emptyDeck:List.of(false,true)){var a=ability("sv6_en_025");var m=abilityGame("sv6_en_025",EnergyType.GRASS);if(emptyDeck)m.drawCardsByEffect(A,A,m.privateView(A).deck().size());int before=m.privateView(A).hand().size();UUID host=bench(m,A);m.useAbility(A,host,a.id());var p=m.effectCardPrompt(A);check(p.minimum()==1&&p.maximum()==1&&p.candidates().stream().allMatch(c->c.definitionId().equals("energy")),"Teal Dance must attach one Basic Grass");reject(()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(hand(m,A,"special").instanceId())));UUID energy=p.candidates().getFirst().instanceId();select(m,List.of(energy));check(m.benchPokemonView(A).getFirst().attachedEnergyIds().contains(energy)&&m.activePokemonView(A).attachedEnergyIds().isEmpty()&&m.privateView(A).hand().size()==before-(emptyDeck?1:0)&&!m.energyAttached(A),"Teal Dance source, draw order or manual quota");reject(()->m.useAbility(A,host,a.id()));}
        var a=ability("sv6_en_025");var m=abilityGame("sv6_en_025",EnergyType.FIRE);var before=m.clientView(A);reject(()->m.useAbility(A,active(m,A),a.id()));check(before.equals(m.clientView(A)),"Teal Dance drew without eligible attachment");
    }
    static void discardCost(){var a=ability("sv10_en_155");for(int size:List.of(1,2)){var m=abilityGame("sv10_en_155",EnergyType.GRASS);m.drawCardsByEffect(A,A,m.privateView(A).deck().size());m.discardHandCardsByEffect(A,A,m.privateView(A).hand().stream().skip(size).map(CardInstance::instanceId).toList());if(size==1){reject(()->m.useAbility(A,active(m,A),a.id()));continue;}m.useAbility(A,active(m,A),a.id());var p=m.effectCardPrompt(A);check(p.minimum()==2&&p.maximum()==2,"Reconstitute exact discard cost");reject(()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(p.candidates().getFirst().instanceId())));select(m,p.candidates().stream().map(CardInstance::instanceId).toList());check(m.privateView(A).hand().isEmpty(),"Cost skipped with empty deck");}}
    static void stadiumPoison(){var a=ability("sv2_en_130");var stadium=GeneratedRuleBatch8Test.trainer("swsh5_en_138");var m=GeneratedRuleBatch8Test.fixture(List.of(a),EnergyType.GRASS,EnergyType.GRASS,stadium,GeneratedRuleBatch8Test.hit(30,false));reject(()->m.useAbility(A,active(m,A),a.id()));m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);m.useAbility(A,bench(m,A),a.id());check(m.activePokemonView(B).conditions().contains(SpecialCondition.POISONED),"Toxic Wetland missing Stadium condition effect");reject(()->m.useAbility(A,bench(m,A),a.id()));}
    static void basicAttachment(){var a=attack("me5-5_en_054",0);var m=game(a);m.attack(A,a.id());var o=m.effectChoicePrompt(A);m.chooseEffectOption(A,o.resolutionId(),o.step(),0);var p=m.effectCardPrompt(A);check(p.minimum()==0&&p.candidates().stream().allMatch(c->m.cardDefinition(c.definitionId()).basicEnergy()),"Zip-Zap allowed Special Energy");var cards=p.candidates().stream().limit(2).map(CardInstance::instanceId).toList();select(m,cards);var d=m.effectAttachmentPrompt(A);m.assignEffectEnergyDistribution(A,d.resolutionId(),d.step(),cards.getFirst(),active(m,A));m.assignEffectEnergyDistribution(A,d.resolutionId(),d.step(),cards.getLast(),bench(m,A));m.confirmEffectEnergyDistribution(A,d.resolutionId(),d.step());check(m.activePokemonView(A).attachedEnergyIds().size()==1&&m.benchPokemonView(A).getFirst().attachedEnergyIds().size()==1,"Basic attachment distribution");}
    static void returnEnergy(){var a=attack("sv5_en_135",0);var m=game(a);var card=hand(m,B,"special");m.attachEnergyByEffect(A,B,EffectSourceZone.HAND,card.instanceId(),B,active(m,B));m.attack(A,a.id());var o=m.effectChoicePrompt(A);m.chooseEffectOption(A,o.resolutionId(),o.step(),0);var p=m.effectCardPrompt(A);check(p.minimum()==1&&p.maximum()==1,"Returning two Energy did not clamp to one physical card");select(m,List.of(card.instanceId()));check(m.activePokemonView(B).attachedEnergyIds().isEmpty()&&m.privateView(B).hand().contains(card),"Returned Special Energy to wrong owner");}
    static void topSupporter(){for(boolean take:List.of(false,true)){var trainer=GeneratedRuleBatch8Test.trainer("sm10_en_182");var m=hpFixture(trainer,500);m.drawCardsByEffect(A,A,m.privateView(A).deck().size());var supporter=hand(m,A,"supporter");var seed=new ArrayList<UUID>();seed.add(supporter.instanceId());seed.addAll(m.privateView(A).hand().stream().filter(c->Set.of("tool","energy").contains(c.definitionId())).limit(6).map(CardInstance::instanceId).toList());m.discardHandCardsByEffect(A,A,seed);m.shuffleDiscardIntoDeckByEffect(A,A);var deck=m.privateView(A).deck();var window=new HashSet<>(deck);int before=m.privateView(A).hand().size();m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);var p=m.effectCardPrompt(A);check(new HashSet<>(p.inspectedCards()).equals(window)&&p.maximum()==1&&p.minimum()==0,"Pokegear inspected wrong window");check(p.candidates().equals(List.of(supporter)),"Pokegear allowed other Trainer kinds or lost Supporter");select(m,take?List.of(supporter.instanceId()):List.of());check(!m.hasPendingEffectChoice()&&m.privateView(A).hand().contains(supporter)==take&&m.privateView(A).hand().size()==before-1+(take?1:0),"Pokegear selection, reveal or conservation");}}

    static void hpBall(){for(int hp:List.of(60,70,80)){var m=hpFixture(GeneratedRuleBatch8Test.trainer("me1_en_167"),hp);m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);if(hp>70&&!m.hasPendingEffectChoice()){check(m.benchPokemonView(A).size()==1,"HP Ball no-match changed Bench");continue;}var p=m.effectCardPrompt(A);check(p.maximum()==2&&p.minimum()==0&&p.candidates().stream().allMatch(c->c.definitionId().equals("basic")),"HP Ball basic filter");check(p.candidates().isEmpty()==(hp>70),"HP Ball printed HP threshold");var ids=p.candidates().stream().limit(2).map(CardInstance::instanceId).toList();int before=m.benchPokemonView(A).size();select(m,ids);check(m.benchPokemonView(A).size()==before+ids.size(),"HP Ball Bench placement");}}
    static void switchAbility(){var a=ability("me2-5_en_152");var m=abilityGame("me2-5_en_152",EnergyType.GRASS);UUID host=bench(m,A);m.useAbility(A,host,a.id());var p=m.effectPokemonPrompt(A);m.chooseEffectPokemon(A,p.resolutionId(),p.step(),host);check(active(m,A).equals(host)&&!m.canUseAbility(A,host,a.id()),"Sky Transport source usage after switch");}
    static void fullProtection(){var a=attack("sm2_en_057",2);var hit=DamageTriggeredAbilityTest.attack(100,",\"conditions\":[{\"target\":\"DEFENDER\",\"condition\":\"POISONED\"}]");var m=SharedUsageLimitTest.attackFixture(1,List.of(),List.of(a,hit));var actor=m.currentPlayer();var opponent=actor.equals(SharedUsageLimitTest.A)?SharedUsageLimitTest.B:SharedUsageLimitTest.A;m.attack(actor,a.id());m.attack(opponent,hit.id());check(m.activePokemonView(actor).damage()==0&&m.activePokemonView(actor).conditions().isEmpty(),"Total Shelter failed damage/effects");m.endTurn(actor);m.attack(opponent,hit.id());check(m.activePokemonView(actor).damage()==110,"Total Shelter did not expire");}
    static ServerMatch hpFixture(TrainerProfile trainer,int hp){
        var abilities=List.<AbilityDefinition>of();var energy=EnergyType.GRASS;var type=EnergyType.GRASS;var attack=GeneratedRuleBatch8Test.hit(20,false);var tags=Map.<String,Set<EnergyType>>of();var RULES=GeneratedRuleBatch19Test.RULES;
        String[] ids={"basic","basic","basic","basic","energy","energy","wrong","special","tool","tool","tool","supporter","trainer","evolved","rulebox"};
        var defs=new ArrayList<CardDefinition>();
        for(String id:Arrays.stream(ids).distinct().toList()){
            boolean pokemon=Set.of("basic","evolved","rulebox").contains(id),isEnergy=Set.of("energy","wrong","special").contains(id);
            defs.add(new CardDefinition(id,id,pokemon?CardCategory.POKEMON:isEnergy?CardCategory.ENERGY:CardCategory.TRAINER,
                id.equals("trainer")?trainer.category():id.equals("supporter")?TrainerCategory.SUPPORTER:id.equals("tool")?TrainerCategory.TOOL:TrainerCategory.NONE,"H",Set.of("international"),
                id.equals("basic")||id.equals("rulebox"),id.equals("energy")||id.equals("wrong"),60,Map.of(),EffectSupport.SUPPORTED,null,
                id.equals("rulebox")?Set.of(PokemonFamily.EX,PokemonFamily.RULE_BOX):Set.of(),pokemon?tags.getOrDefault(id,Set.of(id.equals("evolved")?EnergyType.PSYCHIC:type)):Set.of()));
        }
        var pokemon=new HashMap<String,PokemonProfile>();
        for(String id:List.of("basic","evolved","rulebox"))pokemon.put(id,new PokemonProfile(id.equals("basic")?hp:500,1,id.equals("evolved")?"basic":null,null,0,null,0,
            id.equals("rulebox")?2:1,List.of(id.equals("rulebox")?GeneratedRuleBatch8Test.hit(100,false):attack),id.equals("rulebox")?List.of():abilities,id.equals("evolved")?EnergyType.PSYCHIC:type));
        var combat=new CombatCatalog(pokemon,Map.of("energy",energy,"wrong",energy==EnergyType.FIRE?EnergyType.WATER:EnergyType.FIRE),
            Map.of("trainer",trainer,"tool",DynamicPassiveModifierTest.plainTool()),Map.of("special",EnergyProfile.fixed(energy,2)));
        for(int seed=0;seed<500;seed++){
            var decks=new ArrayList<List<CardInstance>>();for(UUID owner:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(owner.getLeastSignificantBits(),i+1),owner,ids[i%ids.length]));decks.add(cards);}
            var m=new ServerMatch(A,B,decks.get(0),decks.get(1),RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);
            if(List.of(A,B).stream().anyMatch(p->{var basics=m.privateView(p).hand().stream().filter(c->m.cardDefinition(c.definitionId()).basicPokemon()).toList();return basics.size()<2||basics.subList(0,2).stream().anyMatch(c->!c.definitionId().equals("basic"));}))continue;
            OpeningTestSupport.complete(m,A,B,1);m.drawCardsByEffect(A,A,28);m.drawCardsByEffect(A,B,28);m.endTurn(A);m.endTurn(B);
            if(List.of(A,B).stream().allMatch(p->Arrays.stream(ids).allMatch(id->m.privateView(p).hand().stream().anyMatch(c->c.definitionId().equals(id))))&&
                m.privateView(A).hand().stream().filter(c->c.definitionId().equals("energy")).count()>=3&&m.privateView(A).hand().stream().filter(c->c.definitionId().equals("tool")).count()>=3)return m;
        }throw new AssertionError("No batch 8 fixture");
    }

